isVercelTransientError(e: unknown): boolean {
  return (
    (e instanceof VercelError || e instanceof SDKError) &&
    (e.statusCode >= 500 ||
      e.statusCode === Number(HttpStatus.TOO_MANY_REQUESTS))
  )
}

